import {TYPES,SPECIES,REGIONS,MOVES,learnedMoves,equippedMoves,equipMove,migrateMoves,makeState,maxHP,heal,active,encounter,act,validState,validBattle,tile,regionAt,canMove,rng} from './engine.js';
const $=id=>document.getElementById(id),canvas=$('world'),ctx=canvas.getContext('2d'),scene=$('scene');let state=null,battle=null,modal=false,busy=false,sound=false,audioUnlocked=false,movedAt=0,toastTimer,walk=null,drawFrame=0,migratedSave=false;const atlas=new Image();atlas.src='monsters.webp';const worldAtlas=new Image();worldAtlas.src='world.webp';const SAVE='lumina-save-v1',SOUND='lumina-sound-v1';
const sprites=(id,size='',rare=false)=>`<span class="sprite ${rare?'rare':''}" style="background-position:${(id%4)*100/3}% ${Math.floor(id/4)*100/3}%;${size?`width:${size}px;height:${size}px`:''}"></span>`;
const tracks={field:new Audio('audio/field.mp3'),battle:new Audio('audio/battle.mp3'),ending:new Audio('audio/ending.mp3')};for(const a of Object.values(tracks)){a.loop=true;a.volume=.32;a.preload='none';}let currentTrack='field';const effects=Object.fromEntries(['capture','victory','heal','evolve','attack','skill','defeat','click','step'].map(k=>{const a=new Audio('audio/'+k+'.mp3');a.volume=k==='step'?.1:.55;a.preload='none';return[k,a];}));
function soundLabel(){const label=sound?(audioUnlocked?'音 ON':'音 再開'):'音 OFF';$('sound').textContent=label;$('soundLandscape').textContent=label;}
function music(name){if(currentTrack!==name){tracks[currentTrack].pause();currentTrack=name;}if(sound&&!document.hidden)tracks[name].play().then(()=>{audioUnlocked=true;soundLabel();}).catch(()=>{audioUnlocked=false;soundLabel();});}
function beep(freq=500){sfx('click');}
function sfx(name){if(!sound)return;const a=effects[name];if(a){a.currentTime=0;a.play().then(()=>{audioUnlocked=true;soundLabel();}).catch(()=>{});}}
function toast(text){$('toast').textContent=text;$('toast').classList.add('toast-show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('toast-show'),2800);}
function save(preserveBackup=false){if(!state)return;try{const previous=localStorage.getItem(SAVE);if(previous&&!preserveBackup)localStorage.setItem(SAVE+'-backup',previous);localStorage.setItem(SAVE,JSON.stringify({state,battle}));$('saveStatus').textContent='保存済み';}catch{$('saveStatus').textContent='保存できません';toast('端末の保存領域を使えません。メニューからセーブを書き出してください。');}}
function load(raw){const obj=JSON.parse(raw);if(!validState(obj.state)||!validBattle(obj.battle??null,obj.state))throw Error('invalid save');state=obj.state;battle=obj.battle||null;migratedSave=[...state.party,...state.box,...(battle?[battle.enemy,...(battle.roster||[])]:[])].some(m=>m.moves===undefined);migrateMoves(state,battle);}
function escapeText(t){return String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function open(title,content){stopStick();clearInterval(repeat);repeat=null;modal=true;scene.className='scene open';scene.innerHTML=`<div class="modal"><div class="modalHead"><h2>${title}</h2><button id="closeModal" aria-label="閉じる">×</button></div>${content}</div>`;$('closeModal').onclick=close;}
function close(){if(battle){renderBattle();return;}modal=false;scene.className='scene';scene.innerHTML='';draw();}
function start(){open('ルミナ島へようこそ',`<p>島の灯台から光が消えた。四つの番人が持つ紋章を集め、灯台の守護竜に認められよう。</p><p>まずは、旅の相棒を選ぼう。どの仲間もLv.10で進化するよ。</p><div class="starterGrid">${[0,1,2].map(id=>`<button class="starter" data-starter="${id}">${sprites(id)}<b>${SPECIES[id].name}</b><span class="type">${TYPES[SPECIES[id].type]}属性</span></button>`).join('')}</div><p style="margin:16px 0 0"><small>草むらで出会い、戦い、仲間を増やそう。進行は自動で保存。</small></p>`);$('closeModal').hidden=true;scene.querySelectorAll('[data-starter]').forEach(el=>el.onclick=()=>{state=makeState(Number(el.dataset.starter));state.x=8;state.y=10;save();close();update();toast('相棒と冒険へ！ 北西の番人ミナに会おう。');});}
function update(){if(!state)return;const r=REGIONS[state.region];$('location').textContent=r.name;$('badges').textContent=[0,1,2,3].map(i=>state.badges.includes(i)?'◆':'◇').join(' ');$('partyCount').textContent=`${state.party.length} / 6`;$('dexCount').textContent=`${state.caught.length} / 16`;$('coins').textContent=`${state.coins} C`;$('objective').textContent=state.ended?'島に光が戻った！ 図鑑を完成させよう':state.badges.length===4?'島の中央の灯台で守護竜に挑もう。':REGIONS[state.badges.length].hint;const m=state.party[Math.max(0,active(state))];$('lead').innerHTML=`${sprites(m.id)}<small>旅の相棒</small><h2>${SPECIES[m.id].name}</h2><p>Lv.${m.level} · ${TYPES[SPECIES[m.id].type]}属性</p><div class="hp"><i style="width:${100*m.hp/maxHP(m)}%"></i></div><p>HP ${m.hp} / ${maxHP(m)}</p>`;$('progress').innerHTML=REGIONS.map((r,i)=>`<div class="${state.badges.includes(i)?'done':''}">${state.badges.includes(i)?'◆':'◇'} ${r.bossName}</div>`).join('');}
function npcs(){return [...[0,1,2,3].flatMap(i=>{const x=i%2?38:8,y=i>=2?28:8;return [{x:x-1,y:y-1,kind:'heal',label:'診療所',icon:'✚'},{x:x+2,y:y-1,kind:'shop',label:'商店',icon:'◆'}];}),{x:8,y:5,kind:'quest',label:'島の長老',icon:'◈'},...[{x:15,y:8},{x:39,y:12},{x:12,y:28},{x:39,y:28}].map((n,i)=>({...n,kind:'boss',r:i,label:REGIONS[i].bossName,icon:'⚑'})),{x:24,y:17,kind:'final',label:'光の灯台',icon:'✦'}];}
function worldSprite(id,x,y,w,h,flip=false,alpha=1){if(!worldAtlas.complete||!worldAtlas.naturalWidth)return;const c=worldAtlas.naturalWidth/4,d=worldAtlas.naturalHeight/4;ctx.save();ctx.globalAlpha=alpha;if(flip){ctx.translate(x+w,y);ctx.scale(-1,1);ctx.drawImage(worldAtlas,(id%4)*c,Math.floor(id/4)*d,c,d,0,0,w,h);}else ctx.drawImage(worldAtlas,(id%4)*c,Math.floor(id/4)*d,c,d,x,y,w,h);ctx.restore();}
let mapZoom=1.5;try{mapZoom=Number(localStorage.getItem('lumina-zoom-v1'))===1?1:1.5;}catch{}$('zoomBtn').textContent=`拡大 ${mapZoom}×`;$('zoomBtn').onclick=()=>{mapZoom=mapZoom===1.5?1:1.5;try{localStorage.setItem('lumina-zoom-v1',String(mapZoom));}catch{}$('zoomBtn').textContent=`拡大 ${mapZoom}×`;draw();};
function draw(){if(!state){ctx.fillStyle='#588457';ctx.fillRect(0,0,768,576);return;}const rect=canvas.getBoundingClientRect();const h=rect.height/rect.width*768;if(canvas.height!==Math.round(h))canvas.height=Math.round(h);ctx.setTransform(mapZoom,0,0,mapZoom,0,0);const W=canvas.width/mapZoom,H=canvas.height/mapZoom,T=48;let viewX=state.x,viewY=state.y,walkLift=0;if(walk){const p=Math.min(1,(Date.now()-walk.started)/walk.duration),e=1-(1-p)*(1-p);viewX=walk.fromX+(walk.toX-walk.fromX)*e;viewY=walk.fromY+(walk.toY-walk.fromY)*e;walkLift=Math.sin(p*Math.PI)*3;if(p<1&&typeof requestAnimationFrame==='function'&&!drawFrame)drawFrame=requestAnimationFrame(()=>{drawFrame=0;draw();});else if(p>=1){walk=null;drawFrame=0;}}const camX=viewX*T-W/2+T/2,camY=viewY*T-H/2+T/2;ctx.clearRect(0,0,W,H);for(let y=Math.floor(camY/T);y<Math.ceil((camY+H)/T);y++)for(let x=Math.floor(camX/T);x<Math.ceil((camX+W)/T);x++){const t=tile(x,y),r=regionAt(Math.max(0,x),Math.max(0,y));const px=x*T-camX,py=y*T-camY;ctx.fillStyle=t==='path'?'#d1bf84':t==='town'?'#cfccac':t==='water'?'#498fb1':t==='wall'?'#244b52':REGIONS[r]?.color||'#527d59';ctx.fillRect(px,py,T+1,T+1);if((x+y)%2===0){ctx.fillStyle='#ffffff08';ctx.fillRect(px,py,T,T);}if(worldAtlas.complete&&worldAtlas.naturalWidth){const index=t==='tree'?(r===3?5:4):t==='grass'?1:t==='path'?2:t==='town'?8:t==='water'?3:r===1?6:r===2?15:0,hash=Math.abs(Math.imul(x,31)+Math.imul(y,17)),ground=t==='ground';if(!ground||hash%4!==0)worldSprite(index,px,py,T,T,(hash&1)!==0,ground ? .68 : 1);if(ground&&hash%29===0)worldSprite(r===1||r===2?7:r===3?5:4,px+10+(hash%7),py+21,22,22,(hash&2)!==0,.72);}
if(r>state.badges.length){ctx.fillStyle='#10162748';ctx.fillRect(px,py,T,T);}}
for(let i=0;i<4;i++){const x=(i%2?35:5)*T-camX,y=(i>=2?26:6)*T-camY;worldSprite(9,x,y,72,72);}for(const n of npcs()){const x=n.x*T-camX+24,y=n.y*T-camY+24;if(x<-100||x>W+100||y<-100||y>H+100)continue;worldSprite(n.kind==='boss'?13:n.kind==='final'?14:n.kind==='heal'?10:n.kind==='shop'?11:13,x-25,y-25,50,50);ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='13px sans-serif';ctx.fillStyle='#122941';ctx.fillRect(x-56,y-40,112,19);ctx.fillStyle='#fff';ctx.fillText(n.label,x,y-30);}
const px=W/2,py=H/2;worldSprite(12,px-23,py-25-walkLift,46,46);ctx.fillStyle='#0003';ctx.beginPath();ctx.ellipse(px,py+18,13,4,0,0,7);ctx.fill();ctx.font='12px sans-serif';ctx.fillStyle='#ffebaa';ctx.fillText('▼',px,py-28);}
function move(dx,dy){if(!state||modal||battle||busy)return;const now=Date.now();if(now-movedAt<120)return;movedAt=now;const nx=state.x+dx,ny=state.y+dy;state.dir=dy<0?0:dx>0?1:dy>0?2:3;const ok=canMove(state,nx,ny);if(ok==='gate'){toast('先に今のエリアの番人から紋章をもらおう。');return;}if(!ok||npcs().some(n=>n.x===nx&&n.y===ny)){beep(180);return;}walk={fromX:state.x,fromY:state.y,toX:nx,toY:ny,started:Date.now(),duration:110};state.x=nx;state.y=ny;state.region=regionAt(nx,ny);state.steps++;sfx('step');draw();update();if(tile(nx,ny)==='grass'&&state.steps>5&&rng(state)<.23){battle=encounter(state,state.region);save();renderBattle();sfx('attack');}else save();}
function talk(){if(!state||modal||battle)return;const near=npcs().filter(n=>Math.abs(n.x-state.x)+Math.abs(n.y-state.y)<=2).sort((a,b)=>(Math.abs(a.x-state.x)+Math.abs(a.y-state.y))-(Math.abs(b.x-state.x)+Math.abs(b.y-state.y)));const n=near[0];if(!n){toast('人や施設に近づいて「話す / 調べる」を押そう。');return;}if(n.kind==='heal'){heal(state);save();update();toast('仲間が全員元気になった！ 回復は何度でも無料。');sfx('heal');}if(n.kind==='shop')shop();if(n.kind==='quest')quest();if(n.kind==='boss'){if(state.badges.includes(n.r)){open(n.label,`<p>${REGIONS[n.r].rematch}</p><button id="rematch" class="primary">再戦する</button>`);$('rematch').onclick=()=>startBattle(n.r,true);}else if(n.r!==state.badges.length)toast('先に別の番人の紋章が必要だ。');else{open(n.label,`<p>${REGIONS[n.r].challenge}</p><p>相手：${TYPES[SPECIES[REGIONS[n.r].boss].type]}属性 / Lv.${REGIONS[n.r].level+4} · 2体のチーム</p><button id="challenge" class="primary">勝負する</button>`);$('challenge').onclick=()=>startBattle(n.r,true);}}if(n.kind==='final'){if(state.badges.length<4)toast('灯台は静かだ。四つの紋章を集めよう。');else{open('光の灯台',`<p>四つの紋章が輝いた。光の守護竜ルミドラがきみを待っている。</p><p>光・影・岩属性の3体 / Lv.23〜25。島の未来をかけた最後の勝負！</p><button id="finalBattle" class="primary">守護竜に挑む</button>`);$('finalBattle').onclick=()=>startBattle(3,true,true);}}}
function startBattle(r,boss=false,final=false){if(active(state)<0){heal(state);save();}battle=encounter(state,r,boss,final);save();renderBattle();}
function statusText(enemy){const e=battle?.effects?.[enemy?'enemy':'ally']||{};return [['focus','集中'],['weaken','威力↓'],['poison','印']].filter(([key])=>e[key]>0).map(([key,label])=>`${label} ${e[key]}`).join(' / ');}
function stat(m,enemy=false){return `<div class="statbox"><b>${SPECIES[m.id].name}${m.rare?' ✧':''}</b> <small>Lv.${m.level}</small><br><span class="type">${TYPES[SPECIES[m.id].type]}</span><div class="hp"><i style="width:${m.hp/maxHP(m)*100}%;background:${m.hp/maxHP(m)<.3?'#e76a53':'#42b881'}"></i></div><small>HP ${m.hp} / ${maxHP(m)}${enemy&&battle?.boss?` · 残り ${(battle.roster?.length||0)+1}体`:''}${enemy?'':` · 気力 ${'●'.repeat(m.energy)}${'○'.repeat(4-m.energy)}`}</small><small class="status-effects">${statusText(enemy)}</small></div>`;}
function renderBattle(){stopStick();clearInterval(repeat);repeat=null;music('battle');modal=true;scene.className='scene open';const m=state.party[battle.active];scene.innerHTML=`<div class="battle ${battle.result?'result':''}"><div class="battle-field"><div class="enemy-row">${stat(battle.enemy,true)}${sprites(battle.enemy.id,'',battle.enemy.rare)}</div><div class="ally-row">${sprites(m.id,'',m.rare)}${stat(m)}</div></div><div class="battle-log" role="status">${battle.log.slice(-3).map(escapeText).join('<br>')}</div><div class="battle-actions">${battle.result?'<button id="endBattle" class="primary">'+(battle.final&&battle.result==='win'?'島の光を見届ける':'冒険に戻る')+'</button>':`<button data-action="attack" class="primary">攻撃<small>気力 +1</small></button><button id="battleMoves">技<small>装備した${equippedMoves(m).length}技</small></button><button data-action="guard">守る<small>気力 +2</small></button><button data-action="capture" ${battle.boss||state.balls<1?'disabled':''}>捕獲<small>クリスタル ${state.balls}</small></button><button data-action="potion" ${state.potions<1||m.hp===maxHP(m)?'disabled':''}>回復薬<small>残り ${state.potions}</small></button><button id="battleSwitch">交代<small>仲間を選ぶ</small></button><button data-action="run" ${battle.boss?'disabled':''}>逃げる</button>`}</div></div>`;if(battle.result){$('endBattle').onclick=()=>{const ending=battle.final&&battle.result==='win';battle=null;modal=false;music(ending?'ending':'field');save();update();close();if(ending)endingScene();};}else{scene.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>battleAction(el.dataset.action));$('battleSwitch').onclick=()=>party(true);$('battleMoves').onclick=battleMoves;}update();}
function battleAction(action,index){if(busy)return;busy=true;const events=act(state,battle,action,index);save();renderBattle();const effect=battle.result==='capture'?'battle-capture':battle.result==='win'||battle.result==='lose'?'battle-finish':action==='skill'||action==='move'?'battle-skill':action==='attack'?'battle-hit':'';if(effect)scene.classList.add(effect);sfx(battle.result==='capture'?'capture':battle.result==='win'?'victory':battle.result==='lose'?'defeat':events.some(x=>x.includes('進化'))?'evolve':action==='skill'||action==='move'?'skill':action==='attack'?'attack':'click');setTimeout(()=>busy=false,180);}
function battleMoves(){const m=state.party[battle.active];open('使う技を選ぶ',`<p>気力 ${m.energy} / 4。習得・付け替えは戦闘の外で「仲間」から。集中・弱体・印は交代で解除。</p><div class="move-list">${equippedMoves(m).map(v=>`<button data-move="${v.id}" ${m.energy<v.cost||(v.kind==='heal'&&m.hp===maxHP(m))?'disabled':''}><b>${v.name}</b><small>${TYPES[v.type]}属性 · 気力 ${v.cost||'+1'}</small><span>${v.description}</span></button>`).join('')}</div>`);scene.querySelectorAll('[data-move]').forEach(el=>el.onclick=()=>battleAction('move',Number(el.dataset.move)));}
function techniques(collection,index){const m=state[collection][index],equipped=equippedMoves(m);open(`${SPECIES[m.id].name}の技`, `<p>最大4技を装備。レベルが上がると新しい技を覚える。装備中：${equipped.map(v=>v.name).join(' / ')}</p><div class="move-list">${MOVES.filter(v=>v.type===SPECIES[m.id].type).map(v=>`<button data-learned="${v.id}" ${v.level>m.level?'disabled':''}><b>${v.name} ${equipped.some(e=>e.id===v.id)?'●':''}</b><small>Lv.${v.level} · 気力 ${v.cost||'+1'}</small><span>${v.description}</span></button>`).join('')}</div><button id="movesBack">仲間に戻る</button>`);$('movesBack').onclick=()=>party();scene.querySelectorAll('[data-learned]').forEach(el=>el.onclick=()=>{const id=Number(el.dataset.learned);if(equipped.some(v=>v.id===id)){toast('この技は装備中。');return;}open('入れ替える技を選ぶ',`<p>「${MOVES[id].name}」を装備する。</p><div class="move-list">${equipped.map((v,slot)=>`<button data-slot="${slot}">${v.name}と入れ替える</button>`).join('')}${equipped.length<4?`<button data-slot="${equipped.length}">空いている枠に装備</button>`:''}</div><button id="cancelMove">技に戻る</button>`);$('cancelMove').onclick=()=>techniques(collection,index);scene.querySelectorAll('[data-slot]').forEach(button=>button.onclick=()=>{if(equipMove(m,id,Number(button.dataset.slot))){save();update();techniques(collection,index);}});});}
function party(inBattle=false){open(inBattle?'交代する仲間':'仲間とボックス',`<p>${inBattle?'交代すると相手の攻撃を受ける。':'先頭の元気な仲間が戦う。6体まで連れて歩ける。'}</p>${state.party.map((m,i)=>card(m,i,inBattle)).join('')}${!inBattle?`<h2 style="margin:20px 0 10px">ボックス · ${state.box.length}体</h2>${state.box.length?state.box.map((m,i)=>card(m,i,false,true)).join(''):'<p>手持ちが6体になると、新しい仲間はここへ。</p>'}`:''}`);scene.querySelectorAll('[data-tech]').forEach(el=>el.onclick=()=>{const [collection,index]=el.dataset.tech.split(':');techniques(collection,Number(index));});scene.querySelectorAll('[data-switch]').forEach(el=>el.onclick=()=>battleAction('switch',Number(el.dataset.switch)));scene.querySelectorAll('[data-lead]').forEach(el=>el.onclick=()=>{const i=Number(el.dataset.lead);[state.party[0],state.party[i]]=[state.party[i],state.party[0]];save();update();party();});scene.querySelectorAll('[data-box]').forEach(el=>el.onclick=()=>{if(state.party.length===1){toast('手持ちには1体以上必要だよ。');return;}state.box.push(state.party.splice(Number(el.dataset.box),1)[0]);save();party();update();});scene.querySelectorAll('[data-take]').forEach(el=>el.onclick=()=>{if(state.party.length>=6){toast('手持ちをボックスに預けて、空きを作ろう。');return;}state.party.push(state.box.splice(Number(el.dataset.take),1)[0]);save();party();update();});}
function card(m,i,inBattle=false,box=false){return `<div class="card">${sprites(m.id,'',m.rare)}<div class="info"><h3>${SPECIES[m.id].name}${m.rare?' ✧ 星色':''} <span class="type">${TYPES[SPECIES[m.id].type]}</span></h3><p>Lv.${m.level} · HP ${m.hp}/${maxHP(m)}</p><div class="hp"><i style="width:${m.hp/maxHP(m)*100}%"></i></div><small>次のLv.まで ${Math.max(0,m.level*12-m.xp)} EXP${SPECIES[m.id].evolve!==undefined?' · Lv.10で進化':''}</small></div><div class="actions">${inBattle?`<button data-switch="${i}" ${m.hp===0||i===battle.active?'disabled':''}>交代</button>`:box?`<button data-take="${i}">連れる</button><button data-tech="box:${i}">技</button>`:`<button data-lead="${i}" ${i===0?'disabled':''}>先頭</button><button data-box="${i}">預ける</button><button data-tech="party:${i}">技</button>`}</div></div>`;}
function dex(){open('モンスター図鑑',`<p>仲間になった種：${state.caught.length} / 16 · 星色の個体はまれに現れる。</p><div class="dexGrid">${SPECIES.map(s=>`<button class="dexCard ${state.seen.includes(s.id)||state.caught.includes(s.id)?'':'unknown'}" data-dex="${s.id}">${sprites(s.id)}<small>No.${String(s.id+1).padStart(2,'0')} ${state.caught.includes(s.id)?'●':''}</small>${state.seen.includes(s.id)||state.caught.includes(s.id)?s.name:'？？？'}</button>`).join('')}</div>`);scene.querySelectorAll('[data-dex]').forEach(el=>el.onclick=()=>{const s=SPECIES[el.dataset.dex];if(!state.seen.includes(s.id)&&!state.caught.includes(s.id)){toast('まだ出会っていないモンスター。');return;}open(s.name,`${sprites(s.id,150)}<p>${s.description}</p><p>${TYPES[s.type]}属性${s.evolve!==undefined?` · Lv.10で${SPECIES[s.evolve].name}に進化`:''}</p><button id="dexBack">図鑑に戻る</button>`);$('dexBack').onclick=dex;});}
function bag(){open('バッグ',`<p>所持金 <b>${state.coins} C</b></p><div class="shop-row"><div>捕獲クリスタル <b>×${state.balls}</b><br><small>HPが低い野生モンスターほど捕獲しやすい</small></div></div><div class="shop-row"><div>回復薬 <b>×${state.potions}</b><br><small>仲間1体のHPを50回復する</small></div><button id="usePotion">使う</button></div><div class="shop-row"><div>四つの紋章 <b>${state.badges.length} / 4</b></div></div><p style="margin-top:15px">属性相性：草→水・岩、炎→草・風、水→炎・岩、雷→水・風、岩→炎・雷、風→草・岩。光と影は互いに強い。</p>`);$('usePotion').onclick=()=>{if(!state.potions){toast('回復薬がない。');return;}open('回復する仲間',state.party.map((m,i)=>`<div class="card">${sprites(m.id,50)}<div class="info">${SPECIES[m.id].name}<small> HP ${m.hp}/${maxHP(m)}</small></div><button data-heal="${i}" ${m.hp===maxHP(m)?'disabled':''}>回復</button></div>`).join(''));scene.querySelectorAll('[data-heal]').forEach(el=>el.onclick=()=>{const m=state.party[el.dataset.heal];if(state.potions&&m.hp<maxHP(m)){state.potions--;m.hp=Math.min(maxHP(m),m.hp+50);save();update();bag();}});};}
function shop(){open('クリスタル商店',`<p>所持金 <b>${state.coins} C</b></p><div class="shop-row"><div>捕獲クリスタル ×5<br><small>100コイン</small></div><button id="buyBalls" ${state.coins<100?'disabled':''}>買う</button></div><div class="shop-row"><div>回復薬 ×3<br><small>90コイン</small></div><button id="buyPotions" ${state.coins<90?'disabled':''}>買う</button></div><p style="margin-top:16px">コインは戦闘で勝つと手に入る。回復は里の診療所でいつでも無料だよ。</p>`);$('buyBalls').onclick=()=>{if(state.coins>=100){state.coins-=100;state.balls+=5;save();update();shop();beep();}};$('buyPotions').onclick=()=>{if(state.coins>=90){state.coins-=90;state.potions+=3;save();update();shop();beep();}};}
function quest(){const quests=[{goal:3,met:state.captures,name:'モンスターを3体捕獲',reward:'200コインとクリスタル10個'},{goal:10,met:state.wins,name:'戦闘で10回勝利',reward:'300コインと回復薬5個'},{goal:12,met:state.caught.length,name:'図鑑に12種登録',reward:'500コインとクリスタル20個'}];const q=quests[state.quest];open('島の長老',q?`<p>旅をしながら、島の仲間たちについて教えておくれ。</p><p><b>${q.name}</b> · ${Math.min(q.met,q.goal)} / ${q.goal}<br>お礼：${q.reward}</p><button id="claimQuest" class="primary" ${q.met<q.goal?'disabled':''}>報酬を受け取る</button>`:'<p>きみは島のすばらしい研究者になった。ありがとう！ 灯台の光と仲間たちを、これからも守っておくれ。</p>');if(q)$('claimQuest').onclick=()=>{if(q.met<q.goal)return;const i=state.quest++;state.coins+=[200,300,500][i];state.balls+=[10,0,20][i];state.potions+=[0,5,0][i];save();update();quest();};}
function map(){open('ルミナ島の地図',`<p>いまいる場所：${REGIONS[state.region].name}。紋章を集めると、次のエリアへ進める。</p><div class="island">${REGIONS.map((r,i)=>`<button data-travel="${i}" ${i>state.badges.length?'disabled':''} style="border-color:${r.color}"><b>${r.name}</b><span>${i>state.badges.length?'未開放':state.badges.includes(i)?'◆ 紋章獲得':'◇ 番人に挑もう'}</span><span>${i===state.region?'現在地':i>state.badges.length?'':'里へ移動'}</span></button>`).join('')}</div><p style="margin-top:15px"><small>移動は安全な広場へ。番人の旗は、北西(15,8)、北東(39,12)、南西(12,28)、南東(39,28)。灯台は島の中央。</small></p>${state.badges.length===4?'<button id="travelTower" class="primary">灯台へ移動</button>':''}`);scene.querySelectorAll('[data-travel]').forEach(el=>el.onclick=()=>{const i=Number(el.dataset.travel);if(i>state.badges.length)return;state.x=i%2?38:8;state.y=i>=2?30:10;state.region=i;save();close();update();});if($('travelTower'))$('travelTower').onclick=()=>{state.x=24;state.y=19;state.region=3;save();close();update();};}
function menu(){open('冒険メニュー',`<p>プレイ時間 ${Math.floor(state.playSeconds/60)}分 · 勝利 ${state.wins}回 · 捕獲 ${state.captures}体</p><div class="actions"><button id="saveNow" class="primary">セーブする</button><button id="exportSave">セーブを書き出す</button><button id="importSave">セーブを読み込む</button><button id="howTo">遊び方</button><button id="restart">はじめから</button></div><p style="margin-top:18px"><small>自動セーブはこの端末・このブラウザに保存。データを移すときは書き出したファイルを読み込もう。</small></p>`);$('saveNow').onclick=()=>{save();toast('セーブした。');};$('exportSave').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({state,battle:null},null,2)],{type:'application/json'}));a.download='lumina-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};$('importSave').onclick=()=>$('importFile').click();$('howTo').onclick=()=>open('冒険の手引き','<p>① 最初の里で診療所・商店・長老に話す。</p><p>② 草むらで仲間と出会う。攻撃してHPを減らし、捕獲クリスタルを使う。</p><p>③ 戦闘に勝ってレベルを上げる。Lv.10になると進化。攻撃で気力が1、守るで2回復。「技」から攻撃・回復・弱体・防御などを選ぶ。仲間画面で最大4技を付け替えられる。</p><p>④ 四つの番人を順番に倒す。紋章ごとに次のエリアが開放される。島の地図から里に移動できる。</p><p>⑤ 四つの紋章を集め、中央の灯台の守護竜を倒すとエンディング。クリア後も図鑑や星色探しを楽しめる。</p><p>全滅しても仲間は失われず、診療所で全回復する。</p>');$('restart').onclick=()=>{open('冒険をやり直す',`<p>今の進行は上書きされる。残したい場合は、先にセーブを書き出しておこう。</p><div class="actions"><button id="confirmRestart">新しい冒険を始める</button><button id="cancelRestart" class="primary">今の冒険を続ける</button></div>`);$('cancelRestart').onclick=close;$('confirmRestart').onclick=()=>{battle=null;state=null;start();};};}
function endingScene(){open('ルミナ島に光が戻った',`<p>仲間と歩いた森、浜、高原、そして星影の森。四つの紋章が一つになり、消えていた灯台の光が島を照らした。</p>${sprites(14,150)}<p>きみと仲間の絆は、島の新しい伝説になった。</p><p>勝利 ${state.wins}回 · 仲間 ${state.caught.length}種 · 捕獲 ${state.captures}体</p><button id="postgame" class="primary">仲間との旅を続ける</button>`);$('postgame').onclick=()=>{music('field');close();};}
try{sound=localStorage.getItem(SOUND)==='on';}catch{}soundLabel();$('sound').onclick=()=>{sound=!sound;try{localStorage.setItem(SOUND,sound?'on':'off');}catch{}if(sound){soundLabel();music(currentTrack);sfx('click');}else{audioUnlocked=false;Object.values(tracks).forEach(a=>a.pause());Object.values(effects).forEach(a=>a.pause());soundLabel();}};$('soundLandscape').onclick=()=>$('sound').click();$('interact').onclick=talk;$('menu').onclick=()=>state&&!battle&&menu();$('partyBtn').onclick=()=>state&&!battle&&party();$('dexBtn').onclick=()=>state&&!battle&&dex();$('bagBtn').onclick=()=>state&&!battle&&bag();$('mapBtn').onclick=()=>state&&!battle&&map();const dirs={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]};let repeat=null;
// A continuous 360-degree input vector drives cardinal tile movement.
const stick=$('joystick'),knob=$('stickKnob');let stickPointer=null,stickDir=null,stickRepeat=null,controlMode='stick';
function stopStick(){clearInterval(stickRepeat);stickRepeat=null;stickPointer=null;stickDir=null;knob.style.transform='translate(0px, 0px)';}
function setStick(e){if(e.pointerId!==stickPointer)return;const r=stick.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,length=Math.hypot(dx,dy),radius=r.width*.32,scale=length>radius?radius/length:1;knob.style.transform=`translate(${dx*scale}px, ${dy*scale}px)`;stickDir=length<r.width*.12?null:(Math.abs(dx)>Math.abs(dy)?[Math.sign(dx),0]:[0,Math.sign(dy)]);}
function tickStick(){if(stickDir)move(...stickDir);}
stick.addEventListener('pointerdown',e=>{if(stickPointer!==null||modal||battle)return;e.preventDefault();stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);setStick(e);stickRepeat=setInterval(tickStick,145);tickStick();});
stick.addEventListener('pointermove',e=>{if(e.pointerId!==stickPointer)return;e.preventDefault();setStick(e);});
['pointerup','pointercancel','lostpointercapture'].forEach(event=>stick.addEventListener(event,e=>{if(e.pointerId===stickPointer)stopStick();}));
function applyControlMode(){const dpad=controlMode==='dpad';stick.hidden=dpad;document.querySelectorAll('[data-dir]').forEach(el=>{el.hidden=!dpad;});$('controlMode').textContent=dpad?'スティック':'十字キー';}
try{controlMode=localStorage.getItem('lumina-control-v1')==='dpad'?'dpad':'stick';}catch{}applyControlMode();
$('controlMode').onclick=()=>{stopStick();clearInterval(repeat);repeat=null;controlMode=controlMode==='stick'?'dpad':'stick';try{localStorage.setItem('lumina-control-v1',controlMode);}catch{}applyControlMode();};
window.addEventListener('blur',()=>{stopStick();clearInterval(repeat);repeat=null;});
const resumeSound=()=>{if(sound&&!audioUnlocked)music(currentTrack);};document.addEventListener('pointerdown',resumeSound,{capture:true});document.addEventListener('keydown',resumeSound,{capture:true});document.querySelectorAll('[data-dir]').forEach(el=>{const fn=()=>move(...dirs[el.dataset.dir]);el.addEventListener('pointerdown',e=>{e.preventDefault();el.setPointerCapture(e.pointerId);fn();clearInterval(repeat);repeat=setInterval(fn,145);});['pointerup','pointercancel','lostpointercapture'].forEach(event=>el.addEventListener(event,()=>{clearInterval(repeat);repeat=null;}));});let swipe=null;canvas.addEventListener('pointerdown',e=>{if(modal||battle)return;swipe={id:e.pointerId,x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointerup',e=>{if(!swipe||e.pointerId!==swipe.id)return;const dx=e.clientX-swipe.x,dy=e.clientY-swipe.y;swipe=null;if(Math.max(Math.abs(dx),Math.abs(dy))<28)return;e.preventDefault();move(Math.abs(dx)>Math.abs(dy)?Math.sign(dx):0,Math.abs(dy)>=Math.abs(dx)?Math.sign(dy):0);});['pointercancel','lostpointercapture'].forEach(event=>canvas.addEventListener(event,()=>{swipe=null;}));document.addEventListener('keydown',e=>{if(e.repeat)return;const dir=({ArrowUp:'up',w:'up',ArrowDown:'down',s:'down',ArrowLeft:'left',a:'left',ArrowRight:'right',d:'right'})[e.key];if(dir){e.preventDefault();move(...dirs[dir]);}if(e.key===' '||e.key==='Enter'){if(e.target.tagName==='BUTTON')return;e.preventDefault();talk();}if(e.key==='Escape'&&state&&!battle)close();});
$('importFile').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>1000000){toast('セーブファイルが大きすぎます。');return;}try{const oldState=state,oldBattle=battle;try{load(await f.text());}catch(err){state=oldState;battle=oldBattle;throw err;}save();update();if(battle)renderBattle();else close();toast('セーブを読み込んだ。');}catch{toast('このファイルは有効なルミナ島のセーブではありません。');}};
window.addEventListener('resize',draw);window.addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{if(document.hidden){stopStick();clearInterval(repeat);repeat=null;audioUnlocked=false;Object.values(tracks).forEach(a=>a.pause());soundLabel();save();}else if(sound)music(currentTrack);});atlas.onload=draw;worldAtlas.onload=draw;let restoredBackup=false;try{const raw=localStorage.getItem(SAVE);if(raw)load(raw);}catch{try{const backup=localStorage.getItem(SAVE+'-backup');if(backup){load(backup);restoredBackup=true;}}catch{}toast('保存データを確認しました。必要ならセーブファイルを読み込めます。');}if(state){if(migratedSave)save(true);if(restoredBackup){save(true);toast('予備のセーブから冒険を復元しました。');}update();draw();if(battle)renderBattle();}else start();setInterval(()=>{if(state&&!document.hidden){state.playSeconds+=10;save();}},10000);
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
